}" , "memory" : 512 , "maxTotalChargeUsd" : 0.25 } , "id" : "a1000001-0001-4000-8000-000000000002" , "name" : "Run Google Workspace Marketplace Scraper" , "type" : "@apify/n8n-nodes-apify.apify" , "typeVersion" : 1 , "position" : [ 480 , 300 ] } , { "parameters" : { "conditions" : { "options" : { "caseSensitive" : true , "leftValue" : "" , "typeValidation" : "strict" , "version" : 2 } , "conditions" : [ { "id" : "cond-high-risk" , "leftValue" : "={{ $json.oauthSummary?.riskLevel }}" , "rightValue" : "high" , "operator" : { "type" : "string" , "operation" : "equals" } } , { "id" : "cond-neg-reviews" , "leftValue" : "={{ $json.reviewSummary?.negativeReviewCount ?? 0 }}" , "rightValue" : 0 , "operator" : { "type" : "number" , "operation" : "gt" } } ] , "combinator" : "or" } } , "id" : "a1000001-0001-4000-8000-000000000003" , "name" : "High OAuth Risk or 1-2 Star Complaints?" , "type" : "n8n-nodes-base.if" , "typeVersion" : 2.2 , "position" : [ 740 , 300 ] } , { "parameters" : { "mode" : "runOnceForAllItems" , "jsCode" : "const flagged = $input.all().map((item) => item.json);
if (flagged.length === 0) return [];
const highRisk = flagged.filter((a) => a.oauthSummary?.riskLevel === 'high');
const lines = [`*Google Workspace Marketplace Weekly Audit* — ${flagged.length} flagged app(s) (${highRisk.length} high OAuth risk)`, ''];
for (const app of flagged.slice(0, 15)) {
 const installs = app.installCountNumeric ? app.installCountNumeric.toLocaleString('en-US') : (app.installCountLabel || 'N/A');
 const risk = (app.oauthSummary?.riskLevel || 'unknown').toUpperCase();
 const restricted = app.oauthSummary?.restrictedScopeCount ?? 0;
 const neg = app.reviewSummary?.negativeReviewCount ?? 0;
 lines.push(`• *${app.name}* (${installs} installs | ${app.pricingModel}) — OAuth: *${risk}* (${restricted} restricted) | 1-2★ recent: ${neg} | <${app.url}|Listing>`);
}
return [{ json: { flaggedCount: flagged.length, highRiskCount: highRisk.length, message: lines.join('\n') } }];" } , "id" : "a1000001-0001-4000-8000-000000000004" , "name" : "Build Weekly Alert Digest" , "type" : "n8n-nodes-base.code" , "typeVersion" : 2 , "position" : [ 1000 , 240 ] } , { "parameters" : { "method" : "POST" , "url" : "https://hooks.slack.com/services/REPLACE/WITH/YOUR_WEBHOOK" , "sendBody" : true , "specifyBody" : "json" , "jsonBody" : "={{ JSON.stringify({ text: $json.message }) }}" } , "id" : "a1000001-0001-4000-8000-000000000005" , "name" : "Send Alert to Slack / Webhook" , "type" : "n8n-nodes-base.httpRequest" , "typeVersion" : 4.2 , "position" : [ 1260 , 240 ] } ] , "connections" : { "Every Monday at 09:00" : { "main" : [ [ { "node" : "Run Google Workspace Marketplace Scraper" , "type" : "main" , "index" : 0 } ] ] } , "Run Google Workspace Marketplace Scraper" : { "main" : [ [ { "node" : "High OAuth Risk or 1-2 Star Complaints?" , "type" : "main" , "index" : 0 } ] ] } , "High OAuth Risk or 1-2 Star Complaints?" : { "main" : [ [ { "node" : "Build Weekly Alert Digest" , "type" : "main" , "index" : 0 } ] , [ ] ] } , "Build Weekly Alert Digest" : { "main" : [ [ { "node" : "Send Alert to Slack / Webhook" , "type" : "main" , "index" : 0 } ] ] } } } Why No Playwright Is Needed Google Workspace Marketplace embeds structured arrays inside SSR AF_initDataCallback script blocks ( ds:1 for core metadata & exact install counts, ds:5 for OAuth scopes, ds:6 for recent reviews). Running pure TypeScript HTTP + Cheerio instead of headless Chromium keeps typical 5–15 app runs at 2–5 seconds on ~164 MB RAM and puts weekly 25-app monitoring at $0.125/week (~$0.50/month) under $0.005/app Pay-Per-Event pricing (covered by Apify's $5 monthly Free tier credits). Try It and Share Feedback Run on Apify Store: Google Workspace Marketplace Scraper Connect via MCP: https://mcp.apify.com/?tools=fetch-actor-details,Jvccvctus/google-workspace-marketplace-scraper Question for you: How does your team currently audit Google Workspace add-ons before approving domain-wide OAuth access — manual consent review, Google Admin allowlisting, or automated scripts? Drop your workflow below!
